const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path'),fs=require('fs');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{const p=await b.newPage({viewport:{width:390,height:1000}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.click('#learningTab');await p.evaluate(()=>{DEUTSCH_JOURNEY.select(0);sessionStorage.setItem('navGrades',JSON.stringify(DEUTSCH_JOURNEY.islands.map(i=>profileStorage.getItem(i.key))))});
const prev='[data-island-step="-1"]',next='[data-island-step="1"]';if(!await p.locator(prev).isDisabled())throw Error('First boundary');await p.locator(next).click();if(!await p.evaluate(()=>DEUTSCH_JOURNEY.island===1))throw Error('Next arrow');await p.locator(next).press('End');if(!await p.locator(next).isDisabled()||!await p.evaluate(()=>DEUTSCH_JOURNEY.island===3))throw Error('Last boundary');await p.locator(prev).press('Home');if(!await p.locator(prev).isDisabled())throw Error('Home key');
await p.click('.island-atlas-open');if(!await p.locator('dialog[open]').count())throw Error('Atlas closed');await p.click('[data-jump-island="2"]');if(await p.locator('dialog[open]').count()||!await p.evaluate(()=>DEUTSCH_JOURNEY.island===2))throw Error('Atlas selection');if(!await p.locator('.island-atlas-open').evaluate(e=>e===document.activeElement))throw Error('Atlas focus not restored');await p.click('.island-atlas-open');await p.keyboard.press('Escape');if(await p.locator('dialog[open]').count())throw Error('Escape does not close');
// Synthetic touch sequence exercises the swipe threshold without changing vertical scrolling.
await p.locator('.island-picker').dispatchEvent('pointerdown',{clientX:220,clientY:200});await p.locator('.island-picker').dispatchEvent('pointerup',{clientX:90,clientY:202});if(!await p.evaluate(()=>DEUTSCH_JOURNEY.island===3))throw Error('Swipe left');await p.locator('.island-picker').dispatchEvent('pointerdown',{clientX:90,clientY:200});await p.locator('.island-picker').dispatchEvent('pointerup',{clientX:95,clientY:300});if(!await p.evaluate(()=>DEUTSCH_JOURNEY.island===3))throw Error('Vertical movement changed island');
for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:1000});await p.evaluate(()=>DEUTSCH_JOURNEY.map());await p.waitForFunction(()=>{const e=document.querySelector('.island-picker');return Math.abs(e.querySelector('.selected').getBoundingClientRect().left-e.getBoundingClientRect().left)<1});if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Horizontal page overflow '+width);await p.click('.island-atlas-open');if(await p.locator('dialog').evaluate(e=>e.getBoundingClientRect().width>innerWidth))throw Error('Atlas overflow');await p.click('.island-atlas-close')}
await p.emulateMedia({reducedMotion:'reduce'});await p.locator(prev).click();if(await p.locator('.selected').evaluate(e=>e.getAnimations().some(a=>a.playState==='running')))throw Error('Reduced motion ignored');await p.reload();await p.click('#learningTab');if(!await p.evaluate(()=>DEUTSCH_JOURNEY.island===2&&JSON.stringify(DEUTSCH_JOURNEY.islands.map(i=>profileStorage.getItem(i.key)))===sessionStorage.getItem('navGrades')))throw Error('Selection/grades not preserved');
// Scalability fixture: ten indexed choices and a bounded scrollable atlas.
await p.evaluate(()=>{const items=Array.from({length:10},(_,id)=>({id,title:'Test island '+(id+1),image:'',done:0,total:7,passed:false})),fixture=document.createElement('div');fixture.id='navTenFixture';fixture.innerHTML=DEUTSCH_ISLAND_NAV.render({items,active:9,t:(ua,en)=>en});document.querySelector('main').append(fixture)});if(await p.locator('#navTenFixture [data-jump-island]').count()!==10||!await p.locator('#navTenFixture [data-island-step="1"]').isDisabled())throw Error('Ten-island fixture');if(errors.length)throw Error(errors.join(';'));console.log('PASS island navigation: arrows, boundaries, keyboard, direct atlas, focus, Escape, swipe/vertical distinction, selected-card alignment at 320–1280px, reduced motion, persisted selection, unchanged grades and ten-island scale');}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
